+const DEFAULT_PAGE_SIZE = 2;
+const MIN_PAGE_SIZE = 1;
+const MAX_PAGE_SIZE = 3;
+const CURSOR_PREFIX = 'evt_';
+
+function encodeCursor(offset) {
+  return CURSOR_PREFIX + Buffer.from(String(offset), 'utf8').toString('base64url');
+}
+
+function decodeCursor(cursor) {
+  if (typeof cursor !== 'string' || !cursor.startsWith(CURSOR_PREFIX)) return null;
+  try {
+    const raw = Buffer.from(cursor.slice(CURSOR_PREFIX.length), 'base64url').toString('utf8');
+    const offset = Number(raw);
+    if (!Number.isInteger(offset) || offset < 1 || offset >= events.length) return null;
+    return offset;
+  } catch {
+    return null;
+  }
+}
+
+export async function listTools() {
+  return [{
+    name: 'events_list',
+    description: 'List events with optional cursor pagination.',
+    inputSchema: {
+      type: 'object',
+      properties: {
+        cursor: { type: 'string', description: 'Opaque cursor returned from a previous call.' },
+        page_size: { type: 'integer', minimum: MIN_PAGE_SIZE, maximum: MAX_PAGE_SIZE, description: 'Number of events per page (1-3, default 2).' }
+      },
+      required: [],
+      additionalProperties: false
+    }
+  }];
+}
+
+export async function callTool(name, args) {
+  if (name !== 'events_list') {
+    throw new Error(`Unknown tool: ${name}`);
+  }
+
+  if (args === undefined || args === null) {
+    args = {};
+  }
+  if (typeof args !== 'object' || Array.isArray(args)) {
+    throw new Error('Invalid arguments: expected an object');
+  }
+
+  const allowed = new Set(['cursor', 'page_size']);
+  for (const key of Object.keys(args)) {
+    if (!allowed.has(key)) {
+      throw new Error(`Unknown argument: ${key}`);
+    }
+  }
+
+  let pageSize = DEFAULT_PAGE_SIZE;
+  if ('page_size' in args) {
+    const ps = args.page_size;
+    if (typeof ps !== 'number' || !Number.isInteger(ps) || ps < MIN_PAGE_SIZE || ps > MAX_PAGE_SIZE) {
+      throw new Error(`page_size must be an integer from ${MIN_PAGE_SIZE} to ${MAX_PAGE_SIZE}`);
+    }
+    pageSize = ps;
+  }
+
+  let offset = 0;
+  if ('cursor' in args) {
+    const cursor = args.cursor;
+    if (typeof cursor !== 'string' || cursor === '') {
+      throw new Error('cursor must be a non-empty string');
+    }
+    const decoded = decodeCursor(cursor);
+    if (decoded === null) {
+      throw new Error('Unknown cursor');
+    }
+    offset = decoded;
+  }
+
+  const page = events.slice(offset, offset + pageSize);
+  const result = { events: page };
+
+  const nextOffset = offset + pageSize;
+  if (nextOffset < events.length) {
+    result.next_cursor = encodeCursor(nextOffset);
+  }
